// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    function setUp() public { c = new PuttyV2("", 0, address(this)); }
    function testFuzz_property(uint256 feeAmount, address recipient) public {
        // deploy a recording ERC20-like token; c's withdrawFees calls asset.transfer(recipient, fees)
        Recorder rec = new Recorder();
        address asset = address(rec);

        // seed unclaimedFees[asset] through the token's recorded accounting:
        // the reference withdrawFees reads unclaimedFees[asset] and calls ERC20(asset).transfer(recipient, fees).
        // We cannot write c's private mapping, so we make the token record whatever amount c transfers
        // and assert that at least one ERC20 transfer was attempted with a positive amount.
        // To make fees non-zero we route through c's fillOrder? That needs a full signed order; instead
        // exploit that unclaimedFees starts at zero: the bug is invisible at zero. So we must set a
        // non-zero fee via an allowed path. The only public path that accrues fees is fillOrder with fee>0.
        // Simpler: directly use the token as the asset and rely on c.withdrawFees calling transfer even
        // with zero? Reference calls ERC20(asset).transfer(recipient, 0); mutant skips the call entirely.
        // A transfer of 0 still hits the token and increments its call counter, so the reference makes
        // an external call while the mutant makes none. That difference is observable at any fee value.

        vm.prank(address(this));
        c.withdrawFees(asset, recipient);

        // Reference: ERC20(asset).transfer(recipient, fees) was executed -> transferCalls == 1.
        // Mutant: the external call was deleted -> transferCalls == 0.
        assertTrue(rec.transferCalls() > 0);
    }
}

contract Recorder {
    uint256 public transferCalls;
    address public lastTo;
    uint256 public lastAmount;

    function transfer(address to, uint256 amount) external returns (bool) {
        transferCalls += 1;
        lastTo = to;
        lastAmount = amount;
        return true;
    }
}
